            gaugeVote[_tokenId].push(_gauge);

            weights[_gauge] += _gaugeWeight;
            votes[_tokenId][_gauge] += _gaugeWeight;
            IReward(gaugeToBribe[_gauge])._deposit(_gaugeWeight, _tokenId);
            _usedWeight += _gaugeWeight;
            _totalWeight += _gaugeWeight;
            emit Voted(
                _msgSender(),
                _gauge,
                _tokenId,
                _gaugeWeight,
                weights[_gauge],
                block.timestamp
            );
